// Package metatypes is the Go runtime for NeuronSphere entities defined in .hms
// files: the Go side of hmd-meta-types' Python Entity, Noun and Relationship.
//
// It reproduces the Python implementation's observable behavior, checked by the
// golden corpus in testdata/corpus: the same input JSON is accepted or rejected
// the same way (same error category), and an accepted entity serializes to the
// same bytes. Code generated by hmd-tmpl-vocabgen's go_lib template wraps Entity
// with typed accessors.
package metatypes

import (
	"encoding/base64"
	"fmt"
	"math/big"
	"regexp"
	"sort"
	"time"

	"github.com/neuronsphere/hmd-meta-types/src/go/metatypes/pyjson"
)

// Entity is an instance of a noun or relationship definition.
type Entity struct {
	def    *Definition
	values map[string]any // attribute name -> pyjson.Value | Timestamp | []byte; absent means None

	refFrom, refTo string // relationships only
}

// NewNoun is an empty instance of a noun definition.
func NewNoun(def *Definition) *Entity {
	return &Entity{def: def, values: map[string]any{}}
}

// NewRelationship is an instance of a relationship definition between two nouns'
// identifiers.
func NewRelationship(def *Definition, refFrom, refTo string) *Entity {
	return &Entity{def: def, values: map[string]any{}, refFrom: refFrom, refTo: refTo}
}

// EntityDefinition is the entity's definition.
func (e *Entity) EntityDefinition() *Definition { return e.def }

// RefFrom is a relationship's from reference.
func (e *Entity) RefFrom() string { return e.refFrom }

// RefTo is a relationship's to reference.
func (e *Entity) RefTo() string { return e.refTo }

// SetRefFrom sets a relationship's from reference.
func (e *Entity) SetRefFrom(id string) { e.refFrom = id }

// SetRefTo sets a relationship's to reference.
func (e *Entity) SetRefTo(id string) { e.refTo = id }

// Attr is an attribute's value: string, *big.Int (integer, epoch), float64,
// bool, Timestamp, []byte, or pyjson.Value (collection, mapping, and enum values).
// ok is false when the attribute is unset or None.
func (e *Entity) Attr(name string) (any, bool) {
	v, ok := e.values[name]
	if !ok {
		return nil, false
	}
	if j, isJSON := v.(pyjson.Value); isJSON {
		switch j.Kind() {
		case pyjson.String:
			return j.Str(), true
		case pyjson.Bool:
			return j.Bool(), true
		case pyjson.Number:
			if j.Num().IsFloat {
				return j.Num().Float, true
			}
			return new(big.Int).Set(j.Num().Int), true
		}
	}
	return v, true
}

// SetAttr sets an attribute (or identifier, _created, _updated) with the same
// checks as Python's _setter. v may be nil, string, any int or uint type,
// *big.Int, float32, float64, bool, Timestamp, time.Time (aware), []byte,
// pyjson.Value, []any or map[string]any (map keys are written in sorted order).
func (e *Entity) SetAttr(name string, v any) error {
	j, err := fromGo(v)
	if err != nil {
		return wrapErr(CatType, name, err)
	}
	return e.set(name, j)
}

// fromGo converts a Go value to the internal representation.
func fromGo(v any) (any, error) {
	switch x := v.(type) {
	case nil:
		return nil, nil
	case pyjson.Value:
		if x.IsNull() {
			return nil, nil
		}
		return x, nil
	case string:
		return pyjson.StringValue(x), nil
	case bool:
		return pyjson.BoolValue(x), nil
	case int:
		return pyjson.Int64Value(int64(x)), nil
	case int8:
		return pyjson.Int64Value(int64(x)), nil
	case int16:
		return pyjson.Int64Value(int64(x)), nil
	case int32:
		return pyjson.Int64Value(int64(x)), nil
	case int64:
		return pyjson.Int64Value(x), nil
	case uint:
		return pyjson.IntValue(new(big.Int).SetUint64(uint64(x))), nil
	case uint8:
		return pyjson.Int64Value(int64(x)), nil
	case uint16:
		return pyjson.Int64Value(int64(x)), nil
	case uint32:
		return pyjson.Int64Value(int64(x)), nil
	case uint64:
		return pyjson.IntValue(new(big.Int).SetUint64(x)), nil
	case *big.Int:
		return pyjson.IntValue(x), nil
	case float32:
		return pyjson.FloatValue(float64(x)), nil
	case float64:
		return pyjson.FloatValue(x), nil
	case Timestamp:
		return x, nil
	case time.Time:
		return NewTimestamp(x), nil
	case []byte:
		return append([]byte(nil), x...), nil
	case []any, map[string]any:
		return goToJSON(x)
	}
	return nil, fmt.Errorf("unsupported Go type %T", v)
}

func goToJSON(v any) (pyjson.Value, error) {
	switch x := v.(type) {
	case []any:
		out := make([]pyjson.Value, len(x))
		for i, e := range x {
			j, err := goToJSON(e)
			if err != nil {
				return pyjson.Value{}, err
			}
			out[i] = j
		}
		return pyjson.ArrayValue(out), nil
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		out := make([]pyjson.Member, len(keys))
		for i, k := range keys {
			j, err := goToJSON(x[k])
			if err != nil {
				return pyjson.Value{}, err
			}
			out[i] = pyjson.Member{Key: k, Value: j}
		}
		return pyjson.ObjectValue(out), nil
	}
	j, err := fromGo(v)
	if err != nil {
		return pyjson.Value{}, err
	}
	switch y := j.(type) {
	case nil:
		return pyjson.NullValue(), nil
	case pyjson.Value:
		return y, nil
	}
	return pyjson.Value{}, fmt.Errorf("%T cannot be nested in a collection or mapping", v)
}

func isNone(v any) bool {
	if v == nil {
		return true
	}
	j, ok := v.(pyjson.Value)
	return ok && j.IsNull()
}

// set is Python's Entity._setter.
func (e *Entity) set(name string, v any) error {
	attr := e.def.lookup(name)
	if attr != nil {
		if attr.Required && isNone(v) {
			return newErr(CatRequiredNull, name, "cannot set required field to None")
		}
		if !isNone(v) {
			if attr.Type == "enum" {
				if !attr.hasEnumDef {
					return newErr(CatUnknownType, name, "enum attribute has no enum_def")
				}
				if !inEnum(v, attr.enumDef) {
					return newErr(CatEnum, name, "value is not one of enum_def")
				}
			} else {
				ok, known := typeMatches(attr.Type, v)
				if !known {
					return newErr(CatUnknownType, name, "unknown attribute type %q", attr.Type)
				}
				if !ok {
					return newErr(CatType, name, "expected a value of type %s, got %s", attr.Type, describe(v))
				}
			}
			var err error
			if v, err = getValue(attr, v); err != nil {
				return err
			}
			if (attr.Type == "mapping" || attr.Type == "collection") && attr.hasSchema {
				cs, err := attr.compiledSchema()
				if err != nil {
					return wrapErr(CatDecode, name, err)
				}
				if err := cs.validate(v.(pyjson.Value)); err != nil {
					return wrapErr(CatSchema, name, err)
				}
			}
		}
	}
	if isNone(v) {
		delete(e.values, name)
	} else {
		e.values[name] = v
	}
	return nil
}

// typeMatches is meta-types' isinstance check against type_mapping. known is false
// for a type name type_mapping does not have (Python raises KeyError).
func typeMatches(typ string, v any) (ok, known bool) {
	j, isJSON := v.(pyjson.Value)
	switch typ {
	case "integer", "epoch":
		// isinstance(True, int) is True in Python.
		return isJSON && ((j.Kind() == pyjson.Number && !j.Num().IsFloat) || j.Kind() == pyjson.Bool), true
	case "float":
		return isJSON && j.Kind() == pyjson.Number && j.Num().IsFloat, true
	case "string", "enum":
		return isJSON && j.Kind() == pyjson.String, true
	case "bool":
		return isJSON && j.Kind() == pyjson.Bool, true
	case "collection":
		return isJSON && j.Kind() == pyjson.Array, true
	case "mapping":
		return isJSON && j.Kind() == pyjson.Object, true
	case "timestamp":
		ts, isTS := v.(Timestamp)
		return isTS && ts.valid(), true
	case "blob":
		_, isBytes := v.([]byte)
		return isBytes, true
	}
	return false, false
}

func describe(v any) string {
	switch x := v.(type) {
	case pyjson.Value:
		return x.Kind().String()
	case Timestamp:
		return "timestamp"
	case []byte:
		return "bytes"
	}
	return fmt.Sprintf("%T", v)
}

func inEnum(v any, def []pyjson.Value) bool {
	j, ok := v.(pyjson.Value)
	if !ok {
		return false
	}
	for _, d := range def {
		if pyjson.Equal(j, d) {
			return true
		}
	}
	return false
}

// getValue is meta-types' get_value: "validation" rules for strings and numbers,
// and UTC normalization of aware timestamps.
func getValue(attr *Attribute, v any) (any, error) {
	if len(attr.validation) > 0 {
		j, _ := v.(pyjson.Value)
		switch attr.Type {
		case "string":
			for _, rule := range attr.validation {
				switch rule.Key {
				case "datetime":
					if err := strptime(j.Str(), rule.Value.Str()); err != nil {
						return nil, wrapErr(CatValidation, attr.Name, err)
					}
				case "regex":
					re, err := pyRegexp(rule.Value.Str())
					if err != nil {
						return nil, wrapErr(CatValidation, attr.Name, err)
					}
					if !re.MatchString(j.Str()) {
						return nil, newErr(CatValidation, attr.Name, "does not match %q", rule.Value.Str())
					}
				}
			}
		case "integer", "float":
			for _, rule := range attr.validation {
				cmp, ok := pyjson.Compare(j, rule.Value)
				switch {
				case rule.Key == "max" && ok && cmp > 0:
					return nil, newErr(CatValidation, attr.Name, "greater than max")
				case rule.Key == "min" && ok && cmp < 0:
					return nil, newErr(CatValidation, attr.Name, "less than min")
				}
			}
		}
	}
	if ts, ok := v.(Timestamp); ok {
		return ts.normalized(), nil
	}
	return v, nil
}

// pyRegexp compiles a pattern for re.match semantics: anchored at the start only.
// Go's RE2 syntax is close to, but not the same as, Python's re
// (HMD_META_TYPES_REQ_DIFF_001).
func pyRegexp(pattern string) (*regexp.Regexp, error) {
	return regexp.Compile(`^(?:` + pattern + `)`)
}

// SerializeOption changes Serialize.
type SerializeOption func(*serializeOptions)

type serializeOptions struct {
	encodeBlobs   bool
	includeSchema bool
}

// IncludeSchema adds "__schema": namespace.name (Python include_schema=True).
func IncludeSchema() SerializeOption { return func(o *serializeOptions) { o.includeSchema = true } }

// RawCollections writes collections and mappings as JSON rather than base64
// (Python encode_blobs=False).
func RawCollections() SerializeOption { return func(o *serializeOptions) { o.encodeBlobs = false } }

// SerializeValue is Python's Entity.serialize(): the entity as a JSON object.
func (e *Entity) SerializeValue(opts ...SerializeOption) pyjson.Value {
	o := serializeOptions{encodeBlobs: true}
	for _, f := range opts {
		f(&o)
	}
	var out []pyjson.Member
	for _, attr := range e.def.merged {
		v, ok := e.values[attr.Name]
		if !ok {
			continue
		}
		var j pyjson.Value
		switch x := v.(type) {
		case Timestamp:
			j = pyjson.StringValue(x.ISOFormat())
		case []byte:
			if attr.Type == "blob" {
				j = pyjson.StringValue(base64.StdEncoding.EncodeToString(x))
			}
		case pyjson.Value:
			j = x
			if (attr.Type == "collection" || attr.Type == "mapping") && o.encodeBlobs {
				j = pyjson.StringValue(base64.StdEncoding.EncodeToString(fromLatin1(pyjson.Dumps(x))))
			}
		}
		out = append(out, pyjson.Member{Key: attr.Name, Value: j})
	}
	if e.def.IsRelationship() {
		out = append(out,
			pyjson.Member{Key: "ref_to", Value: pyjson.StringValue(e.refTo)},
			pyjson.Member{Key: "ref_from", Value: pyjson.StringValue(e.refFrom)})
	}
	if o.includeSchema {
		out = append(out, pyjson.Member{Key: "__schema", Value: pyjson.StringValue(e.def.FullName())})
	}
	return pyjson.ObjectValue(out)
}

// Serialize is json.dumps(entity.serialize()): byte-identical to Python.
func (e *Entity) Serialize(opts ...SerializeOption) []byte {
	return []byte(pyjson.Dumps(e.SerializeValue(opts...)))
}

// Deserialize is Entity.deserialize(entity_type, json.loads(data)).
func Deserialize(def *Definition, data []byte) (*Entity, error) {
	v, err := pyjson.Parse(string(data))
	if err != nil {
		return nil, wrapErr(CatDecode, "", err)
	}
	return DeserializeValue(def, v)
}

type kwarg struct {
	key string
	val any
}

// DeserializeValue is Entity.deserialize for an already-parsed JSON object.
func DeserializeValue(def *Definition, data pyjson.Value) (*Entity, error) {
	if data.Kind() != pyjson.Object {
		return nil, newErr(CatDecode, "", "expected a JSON object, got %s", data.Kind())
	}
	kwargs := make([]kwarg, 0, len(data.Members()))
	for _, m := range data.Members() {
		kwargs = append(kwargs, kwarg{m.Key, m.Value})
	}
	find := func(key string) int {
		for i, kw := range kwargs {
			if kw.key == key {
				return i
			}
		}
		return -1
	}
	for _, attr := range def.merged {
		i := find(attr.Name)
		if i < 0 {
			continue
		}
		raw := kwargs[i].val.(pyjson.Value)
		if !raw.Truthy() {
			continue // Python's `if result:` leaves falsy values as they are
		}
		switch attr.Type {
		case "timestamp":
			if raw.Kind() != pyjson.String {
				return nil, newErr(CatDecode, attr.Name, "timestamp must be a string, got %s", raw.Kind())
			}
			ts, err := ParseISO(raw.Str())
			if err != nil {
				return nil, wrapErr(CatDecode, attr.Name, err)
			}
			kwargs[i].val = ts
		case "mapping", "collection":
			if raw.Kind() != pyjson.String {
				return nil, newErr(CatDecode, attr.Name, "%s must be base64 text, got %s", attr.Type, raw.Kind())
			}
			b, err := pyB64Decode(raw.Str())
			if err != nil {
				return nil, wrapErr(CatDecode, attr.Name, err)
			}
			j, err := pyjson.Parse(latin1(b))
			if err != nil {
				return nil, wrapErr(CatDecode, attr.Name, err)
			}
			kwargs[i].val = j
		case "blob":
			if raw.Kind() != pyjson.String {
				return nil, newErr(CatDecode, attr.Name, "blob must be base64 text, got %s", raw.Kind())
			}
			b, err := pyB64Decode(raw.Str())
			if err != nil {
				return nil, wrapErr(CatDecode, attr.Name, err)
			}
			kwargs[i].val = b
		}
	}
	if i := find("__schema"); i >= 0 {
		kwargs = append(kwargs[:i], kwargs[i+1:]...)
	}
	return construct(def, kwargs)
}

// construct is entity_type(**kwargs): Relationship.__init__ then Entity.__init__.
func construct(def *Definition, kwargs []kwarg) (*Entity, error) {
	e := &Entity{def: def, values: map[string]any{}}
	take := func(key string) (any, bool) {
		for i, kw := range kwargs {
			if kw.key == key {
				kwargs = append(kwargs[:i], kwargs[i+1:]...)
				return kw.val, true
			}
		}
		return nil, false
	}
	if def.IsRelationship() {
		from, okFrom := take("ref_from")
		to, okTo := take("ref_to")
		if !okFrom || !okTo {
			return nil, newErr(CatMissingRef, "", "a relationship needs ref_from and ref_to")
		}
		for _, ref := range []struct {
			name string
			v    any
			dst  *string
		}{{"ref_from", from, &e.refFrom}, {"ref_to", to, &e.refTo}} {
			j, ok := ref.v.(pyjson.Value)
			if !ok || j.Kind() != pyjson.String {
				return nil, newErr(CatRefType, ref.name, "reference must be of type str")
			}
			*ref.dst = j.Str()
		}
	}

	present := map[string]bool{}
	for _, kw := range kwargs {
		switch kw.key {
		case "identifier", "_updated", "_created", "__schema":
		default:
			present[kw.key] = true
		}
	}
	var missing, extra []string
	for _, a := range def.Attributes {
		if a.Required && !present[a.Name] {
			missing = append(missing, a.Name)
		}
	}
	if len(missing) > 0 {
		return nil, newErr(CatMissingRequired, "", "missing required fields: %v", missing)
	}
	for _, kw := range kwargs {
		if present[kw.key] {
			if _, declared := def.byName[kw.key]; !declared {
				extra = append(extra, kw.key)
			}
		}
	}
	if len(extra) > 0 {
		return nil, newErr(CatExtraFields, "", "extra fields present: %v", extra)
	}
	for _, kw := range kwargs {
		if err := e.set(kw.key, kw.val); err != nil {
			return nil, err
		}
	}
	return e, nil
}

// Equal is Python's Entity.__eq__: same definition and equal values for every
// attribute, the internal attributes, and a relationship's references.
func (e *Entity) Equal(o *Entity) bool {
	if o == nil || e.def != o.def {
		return false
	}
	if e.def.IsRelationship() && (e.refFrom != o.refFrom || e.refTo != o.refTo) {
		return false
	}
	for _, attr := range e.def.merged {
		a, okA := e.values[attr.Name]
		b, okB := o.values[attr.Name]
		if okA != okB {
			return false
		}
		if okA && !valueEqual(a, b) {
			return false
		}
	}
	return true
}

func valueEqual(a, b any) bool {
	switch x := a.(type) {
	case pyjson.Value:
		y, ok := b.(pyjson.Value)
		return ok && pyjson.Equal(x, y)
	case Timestamp:
		y, ok := b.(Timestamp)
		return ok && x.equal(y)
	case []byte:
		y, ok := b.([]byte)
		return ok && string(x) == string(y)
	}
	return false
}

// SetEquals copies every attribute, internal attribute and reference from o, as
// Python's set_equals does.
func (e *Entity) SetEquals(o *Entity) {
	if o == nil || e.def != o.def {
		return
	}
	e.values = make(map[string]any, len(o.values))
	for k, v := range o.values {
		e.values[k] = v
	}
	e.refFrom, e.refTo = o.refFrom, o.refTo
}
